(()=>{
const canvas=document.querySelector('#board'),ctx=canvas.getContext('2d'),economy=window.PixelEconomy,distanceEl=document.querySelector('#distance'),coinsEl=document.querySelector('#coins'),bestEl=document.querySelector('#best'),status=document.querySelector('#status'),overlay=document.querySelector('#overlay'),finalScore=document.querySelector('#final-score');
const W=canvas.width,H=canvas.height,horizon=55,roadBottom=352;
let lane=1,jumpTime=0,slideTime=0,runDistance=0,coins=0,best=+(localStorage.subwayDashBest||0),speed=.29,spawnTimer=1.1,coinTimer=.45,obstacles=[],pickups=[],running=true,lastTime=0,clock=0,raf,lastLane=1;
bestEl.textContent=best;
function roadWidth(z){return 118+z*478}function laneX(which,z){return W/2+(which-1)*roadWidth(z)/3}function groundY(z){return horizon+z*z*(roadBottom-horizon)}
function changeLane(direction){if(!running)return;lane=Math.max(0,Math.min(2,lane+direction))}
function doJump(){if(running&&jumpTime<=0&&slideTime<=0)jumpTime=.78}
function doSlide(){if(running&&slideTime<=0&&jumpTime<=0)slideTime=.72}
function spawnObstacle(){let nextLane=Math.floor(Math.random()*3);if(nextLane===lastLane&&Math.random()<.72)nextLane=(nextLane+1+Math.floor(Math.random()*2))%3;lastLane=nextLane;const roll=Math.random();obstacles.push({lane:nextLane,z:0,type:roll<.42?'train':roll<.72?'barrier':'beam',hit:false})}
function spawnCoins(){const which=Math.floor(Math.random()*3);for(let i=0;i<4;i++)pickups.push({lane:which,z:-i*.12,taken:false})}
function reset(){lane=1;jumpTime=0;slideTime=0;runDistance=0;coins=0;speed=.29;spawnTimer=.8;coinTimer=.3;obstacles=[];pickups=[];running=true;lastLane=1;clock=0;distanceEl.textContent='0';coinsEl.textContent='0';status.textContent='Switch lanes, jump barriers, slide under beams.';overlay.hidden=true;lastTime=performance.now();cancelAnimationFrame(raf);raf=requestAnimationFrame(frame)}
function collide(){running=false;const d=Math.floor(runDistance);if(d>best){best=d;localStorage.subwayDashBest=best;bestEl.textContent=best}status.textContent='Bonk! Pick a lane and try again.';finalScore.textContent='Distance: '+d+' m  ·  Coins: '+coins;overlay.hidden=false}
function update(dt){clock+=dt;runDistance+=speed*dt*20;speed=Math.min(.49,speed+dt*.0021);distanceEl.textContent=Math.floor(runDistance);if(jumpTime>0)jumpTime=Math.max(0,jumpTime-dt);if(slideTime>0)slideTime=Math.max(0,slideTime-dt);spawnTimer-=dt;coinTimer-=dt;if(spawnTimer<=0){spawnObstacle();spawnTimer=Math.max(1.08,1.42-(speed-.29)*1.15)}if(coinTimer<=0){spawnCoins();coinTimer=1.65+Math.random()*.45}
for(const o of obstacles){const before=o.z;o.z+=speed*dt;if(!o.hit&&before<.91&&o.z>=.91&&o.lane===lane){const safe=o.type==='train'?false:o.type==='barrier'?jumpTime>0:slideTime>0;if(!safe){collide();return}o.hit=true}}
for(const c of pickups){c.z+=speed*dt;if(economy.owns('coin_magnet')&&c.z>.25&&c.z<.84&&Math.abs(c.lane-lane)===1)c.lane=lane;if(!c.taken&&c.z>=.88&&c.z<.97&&c.lane===lane){c.taken=true;coins++;coinsEl.textContent=coins;economy.award(1);status.textContent='Coin collected! +1 Pixel Point.'}}
obstacles=obstacles.filter(o=>o.z<1.08);pickups=pickups.filter(c=>c.z<1.08&&!c.taken);
}
function drawRoad(){ctx.fillStyle='#171e24';ctx.fillRect(0,0,W,H);const top=horizon,bottom=roadBottom,topWidth=118,bottomWidth=596;ctx.fillStyle='#273237';ctx.beginPath();ctx.moveTo(W/2-topWidth/2,top);ctx.lineTo(W/2+topWidth/2,top);ctx.lineTo(W/2+bottomWidth/2,bottom);ctx.lineTo(W/2-bottomWidth/2,bottom);ctx.closePath();ctx.fill();ctx.fillStyle='#202a2f';ctx.fillRect(0,0,W,horizon);ctx.fillStyle='#243037';ctx.fillRect(0,horizon-8,76,H-horizon);ctx.fillRect(W-76,horizon-8,76,H-horizon);
for(let k=0;k<4;k++){const xTop=W/2-topWidth/2+topWidth*k/3,xBottom=W/2-bottomWidth/2+bottomWidth*k/3;ctx.strokeStyle=k===0||k===3?'#72807955':'#72807935';ctx.lineWidth=k===0||k===3?3:2;ctx.beginPath();ctx.moveTo(xTop,top);ctx.lineTo(xBottom,bottom);ctx.stroke()}
const offset=(clock*speed*1.8)%1;for(let i=0;i<9;i++){const z=(i/8+offset)%1,y=groundY(z),half=roadWidth(z)/2;ctx.strokeStyle='#71807955';ctx.lineWidth=1+z*2;ctx.beginPath();ctx.moveTo(W/2-half,y);ctx.lineTo(W/2+half,y);ctx.stroke()}
for(let i=0;i<5;i++){const y=horizon+20+i*42;ctx.fillStyle='#344147';ctx.fillRect(12,y,45,3);ctx.fillRect(W-57,y,45,3)}
}
function drawObstacle(o){const z=Math.max(0,o.z),x=laneX(o.lane,z),base=groundY(z),scale=.23+z*.92,laneW=roadWidth(z)/3;if(o.type==='train'){const w=laneW*.72,h=104*scale;ctx.fillStyle='#65716d';ctx.fillRect(x-w/2,base-h,w,h);ctx.fillStyle='#829087';ctx.fillRect(x-w/2,base-h,w,8*scale);ctx.fillStyle='#34484a';for(let r=0;r<3;r++)ctx.fillRect(x-w*.34,base-h+(18+r*22)*scale,w*.68,13*scale);ctx.fillStyle='#a8856d';ctx.fillRect(x-w*.39,base-5*scale,w*.78,5*scale)}else if(o.type==='barrier'){const w=laneW*.67,h=27*scale;ctx.fillStyle='#98705f';ctx.fillRect(x-w/2,base-h,w,h);ctx.fillStyle='#c29a78';ctx.fillRect(x-w/2,base-h,w,5*scale);ctx.fillStyle='#354043';ctx.fillRect(x-w*.35,base-h*.45,w*.7,3*scale)}else{const w=laneW*.76,h=13*scale,top=base-49*scale;ctx.fillStyle='#8c7061';ctx.fillRect(x-w/2,top,w,h);ctx.fillStyle='#b69477';ctx.fillRect(x-w/2,top,w,4*scale);ctx.fillRect(x-w*.42,top,4*scale,50*scale);ctx.fillRect(x+w*.38,top,4*scale,50*scale)}}
function drawCoin(c){const z=Math.max(0,c.z),x=laneX(c.lane,z),y=groundY(z)-15*(.3+z),r=3+z*5;ctx.fillStyle='#bb896d';ctx.beginPath();ctx.ellipse(x,y,r,r*1.25,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#e0b78f';ctx.lineWidth=Math.max(1,z*2);ctx.stroke()}
function drawRunner(){const z=.97,x=laneX(lane,z),ground=groundY(z);const jumpProgress=jumpTime>0?1-jumpTime/.78:1;const lift=jumpTime>0?Math.sin(jumpProgress*Math.PI)*54:0;const sliding=slideTime>0;const h=sliding?19:43,w=sliding?38:24,y=ground-h-lift;ctx.fillStyle='#0d1418aa';ctx.beginPath();ctx.ellipse(x,ground+2,sliding?25:17,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#66534c';ctx.fillRect(x-w*.38,y+h-6,7,7);ctx.fillRect(x+w*.05,y+h-6,7,7);if(sliding){ctx.fillStyle='#8fc4aa';ctx.fillRect(x-w/2,y+5,w,13);ctx.fillStyle='#c99d7d';ctx.fillRect(x+w*.08,y,14,13)}else{ctx.fillStyle='#8fc4aa';ctx.fillRect(x-9,y+17,18,21);ctx.fillStyle='#bb896d';ctx.fillRect(x-10,y+30,20,4);ctx.fillStyle='#c99d7d';ctx.fillRect(x-7,y+5,14,14);ctx.fillStyle='#78aaa4';ctx.fillRect(x-8,y+2,16,6);ctx.fillStyle='#28353a';ctx.fillRect(x-4,y+11,2,2);ctx.fillRect(x+3,y+11,2,2)}}
function draw(){drawRoad();for(const o of obstacles)drawObstacle(o);for(const c of pickups)drawCoin(c);drawRunner()}
function frame(now){if(!running)return;const dt=Math.min(.05,Math.max(0,(now-lastTime)/1000));lastTime=now;update(dt);draw();if(running)raf=requestAnimationFrame(frame)}
function action(a){if(a==='left')changeLane(-1);else if(a==='right')changeLane(1);else if(a==='jump')doJump();else if(a==='slide')doSlide()}
document.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' '].includes(e.key))e.preventDefault();if(e.repeat)return;if(e.key==='ArrowLeft'||e.key.toLowerCase()==='a')action('left');if(e.key==='ArrowRight'||e.key.toLowerCase()==='d')action('right');if(e.key==='ArrowUp'||e.key===' ')action('jump');if(e.key==='ArrowDown'||e.key.toLowerCase()==='s')action('slide')});
document.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('pointerdown',e=>{e.preventDefault();action(button.dataset.action)}));
let touchStart=null;canvas.addEventListener('touchstart',e=>{touchStart={x:e.changedTouches[0].clientX,y:e.changedTouches[0].clientY}},{passive:true});canvas.addEventListener('touchend',e=>{if(!touchStart)return;const dx=e.changedTouches[0].clientX-touchStart.x,dy=e.changedTouches[0].clientY-touchStart.y;if(Math.max(Math.abs(dx),Math.abs(dy))>22){if(Math.abs(dx)>Math.abs(dy))action(dx<0?'left':'right');else action(dy<0?'jump':'slide')}touchStart=null},{passive:true});
document.querySelector('#restart').addEventListener('click',reset);document.querySelector('#overlay-restart').addEventListener('click',reset);reset();
})();
